        relationships = {}
        if source_id is not None:
            relationships[NodeRelationship.SOURCE] = RelatedNodeInfo(
                node_id=source_id
            )

        if self.include_properties:
            text = f"{triplet[0]!s} -> {triplet[1]!s} -> {triplet[2]!s}"
